// Generated from the vendored kit stylesheet (kit/tokens) (lab/library at 8fbfb912); do not edit. The kit's design
// tokens as text, for the worker's DOM and for each drawing's own style (TEACH-247 part h).
export const KIT_TOKENS =
  '/* Dayback teaching-model kit: tokens, themes and build styles.\n   Extracted from north-star/index.html (v3, 7 Oct 2026) and generalised.\n   Diagrams reference ONLY these names, never raw values. */\n@import url("https://fonts.googleapis.com/css2?family=Archivo:wght@600;700;800&family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Inter:wght@400;500;600;700&family=Lexend:wght@400;500;600;700&display=swap");\n/* ---- 1. MOTION TOKENS (shared by every theme) ---- */\n:root {\n  --t-quick: 180ms; /* small state changes, fades of single marks      */\n  --t-base: 420ms; /* an element entering                             */\n  --t-move: 720ms; /* an object travelling from A to B                */\n  --t-draw: 900ms; /* a line or arrow drawing on                      */\n  /* build pacing (v3): the teacher advances every step, nothing runs on a timer */\n  --t-build-enter: 900ms; /* an element fading or rising in during a build     */\n  --t-build-move: 1200ms; /* an object travelling during a build                */\n  --t-build-draw: 1400ms; /* a line or arrow drawing on during a build          */\n  --t-recede: 700ms; /* an earlier annotation stepping back to quiet       */\n  --pace: 1.6; /* scales scripted delays and motion inside a step    */\n  --loop-vapour: 2.6s;\n  --loop-rain: 1.7s;\n  --loop-river: 2.4s; /* gentle loop periods */\n  --stagger: 60ms; /* gap between items revealed as a set             */\n  --ease-out: cubic-bezier(0.22, 1, 0.36, 1); /* enter: fast start, soft landing */\n  --ease-io: cubic-bezier(0.65, 0, 0.35, 1); /* move and draw: A to B           */\n  --ease-in: cubic-bezier(0.55, 0, 1, 0.45); /* exit                            */\n  --ease-settle: cubic-bezier(\n    0.34,\n    1.3,\n    0.64,\n    1\n  ); /* small arrival overshoot, objects landing only */\n  /* receding (legibility pass, 8 Oct): text in any muted token (ink-3 included) keeps >= 3:1 against its ground when quiet,\n     and ink and ink-2 keep >= 4.5:1 when soft, in every theme */\n  --recede-quiet: 0.8;\n  --recede-soft: 0.9;\n}\n/* ---- 2. SHARED LAYER: scale, spacing, depth, meaning colours (derived from theme hues) ---- */\n.tk {\n  /* type scale, in slide units (canvas is 1280 x 720) */\n  --fs-title: 46px;\n  --fs-h3: 32px;\n  --fs-label: 30px;\n  --fs-cap: 26px;\n  --fs-small: 24px;\n  --fs-min: 24px; /* floor for any text: 24 units = 1/30 of the slide height (legibility pass, 8 Oct) */\n  --fs-num: 40px;\n  --fs-big: 52px;\n  --fs-eq: 60px;\n  --fs-badge: 24px;\n  /* spacing, in slide units (read by the layout code) */\n  --space-edge: 64;\n  --space-title: 78;\n  --space-foot: 660;\n  --space-gap: 24;\n  --pill-h: 54;\n  --pill-pad: 22;\n  --label-gap: 14;\n  /* arrowheads: length in slide units, shared by every arrow */\n  --head: 16;\n  /* depth levels */\n  --depth-far: 38%; /* far planes: hue mixed with haze  */\n  --depth-mid: 72%; /* middle planes                    */\n  --depth-shade: 78%; /* shaded face: hue mixed with --shade */\n\n  /* ---- meaning colours, derived from the theme\'s hues ---- */\n  --water: var(--hue-blue);\n  --water-hi: color-mix(in oklab, var(--hue-blue) 32%, var(--paper));\n  --vapour: color-mix(in oklab, var(--hue-blue) 62%, var(--bg));\n  --heat: var(--hue-red);\n  --sun: var(--hue-gold);\n  --haze: color-mix(in oklab, var(--hue-blue) 12%, var(--bg));\n  --sky-top: color-mix(in oklab, var(--hue-blue) 30%, var(--bg));\n  --sky-bot: color-mix(in oklab, var(--hue-blue) 7%, var(--bg));\n  --sea-1: color-mix(in oklab, var(--hue-blue) 52%, var(--bg));\n  --sea-2: color-mix(in oklab, var(--hue-blue) 76%, var(--bg));\n  --sea-3: var(--hue-blue);\n  --sea-hi: color-mix(in oklab, var(--hue-blue) 22%, var(--bg));\n  --hill-far: color-mix(in oklab, var(--hue-green) var(--depth-far), var(--haze));\n  --hill-mid: color-mix(in oklab, var(--hue-green) var(--depth-mid), var(--haze));\n  --hill-near: var(--hue-green);\n  --hill-shade: color-mix(in oklab, var(--hue-green) var(--depth-shade), var(--shade));\n  --cloud-shade: color-mix(in oklab, var(--cloud) 80%, var(--hue-blue));\n  --life: var(--hue-green);\n  --life-shade: color-mix(in oklab, var(--hue-green) var(--depth-shade), var(--shade));\n  --energy: var(--hue-gold);\n  --lost: var(--hue-red);\n  --lost-pale: color-mix(in oklab, var(--hue-red) 14%, var(--bg));\n  --rabbit: var(--hue-brown);\n  --rabbit-shade: color-mix(in oklab, var(--hue-brown) var(--depth-shade), var(--shade));\n  --fox: var(--hue-orange);\n  --fox-shade: color-mix(in oklab, var(--hue-orange) var(--depth-shade), var(--shade));\n  --fur-light: color-mix(in oklab, var(--cloud) 88%, var(--hue-gold));\n  --ear: color-mix(in oklab, var(--hue-red) 40%, var(--paper));\n  --ground-shadow: color-mix(in oklab, var(--shade) var(--shadow-k), transparent);\n  --counter: var(--hue-orange);\n  --counter-edge: color-mix(in oklab, var(--hue-orange) var(--depth-shade), var(--shade));\n  --plate: color-mix(in oklab, var(--hue-gold) 16%, var(--bg));\n  --part: var(--hue-purple);\n  --part-pale: color-mix(in oklab, var(--hue-purple) 18%, var(--bg));\n  --shape: var(--paper);\n  --era-bc: color-mix(in oklab, var(--hue-brown) 50%, var(--bg));\n  --era-ad: color-mix(in oklab, var(--hue-orange) 60%, var(--bg));\n  --event: var(--hue-red);\n  --particle: var(--hue-blue);\n  --particle-edge: color-mix(in oklab, var(--hue-blue) 62%, var(--shade));\n  --s-hot: var(--hue-red);\n  --s-hot-pale: color-mix(in oklab, var(--hue-red) 16%, var(--paper));\n  --s-cool: var(--hue-blue);\n  --s-cool-pale: color-mix(in oklab, var(--hue-blue) 16%, var(--paper));\n  --p-info: var(--hue-blue);\n  --p-maint: var(--hue-teal);\n  --p-retr: var(--hue-gold);\n  --p-forget: var(--ink-3);\n  --atom-a: var(--hue-blue);\n  --atom-b: var(--hue-gold);\n  --sun-body: var(--hue-gold);\n  --mercury: var(--hue-grey);\n  --venus: color-mix(in oklab, var(--hue-gold) 55%, var(--hue-grey));\n  --earth: var(--hue-blue);\n  --earth-land: var(--hue-green);\n  --mars: var(--hue-red);\n  --moon: color-mix(in oklab, var(--hue-grey) 60%, var(--paper));\n  --orbit: color-mix(in oklab, var(--ink) 30%, var(--bg));\n  /* readable text versions of each meaning colour: mixing with ink darkens on\n     light grounds and lightens on dark grounds, so one rule works in every theme */\n  --water-text: color-mix(in oklab, var(--hue-blue) 72%, var(--ink));\n  --heat-text: color-mix(in oklab, var(--hue-red) 72%, var(--ink));\n  --energy-text: color-mix(in oklab, var(--hue-gold) 62%, var(--ink));\n  --part-text: color-mix(in oklab, var(--hue-purple) 72%, var(--ink));\n  --teal-text: color-mix(in oklab, var(--hue-teal) 72%, var(--ink));\n  --event-text: color-mix(in oklab, var(--hue-red) 72%, var(--ink));\n  --era-bc-text: color-mix(in oklab, var(--hue-brown) 60%, var(--ink));\n  --era-ad-text: color-mix(in oklab, var(--hue-orange) 60%, var(--ink));\n  --p-info-text: color-mix(in oklab, var(--hue-blue) 72%, var(--ink));\n  --p-maint-text: color-mix(in oklab, var(--hue-teal) 72%, var(--ink));\n  --p-retr-text: color-mix(in oklab, var(--hue-gold) 62%, var(--ink));\n  --s-hot-text: color-mix(in oklab, var(--hue-red) 72%, var(--ink));\n  --s-cool-text: color-mix(in oklab, var(--hue-blue) 72%, var(--ink));\n  /* ---- v2 scene tokens: real objects and places, all mixed from the theme\'s hues ---- */\n  --sw-lens: calc(var(--sw-struct) * 2);\n  --wall-top: color-mix(in oklab, var(--hue-blue) 9%, var(--bg));\n  --wall-bot: color-mix(in oklab, var(--hue-gold) 7%, var(--bg));\n  --bench-top: color-mix(in oklab, var(--hue-brown) 30%, var(--bg));\n  --bench-front: color-mix(in oklab, var(--hue-brown) 52%, var(--bg));\n  --bench-edge: color-mix(in oklab, var(--hue-brown) 70%, var(--shade));\n  --cone: color-mix(in oklab, var(--ink) 6%, transparent);\n  --cone-edge: color-mix(in oklab, var(--ink) 28%, transparent);\n  --lens-bg: var(--paper);\n  --lens-rim: var(--ink-2);\n  --ice: color-mix(in oklab, var(--hue-blue) 20%, var(--cloud));\n  --ice-top: color-mix(in oklab, var(--hue-blue) 8%, var(--cloud));\n  --ice-side: color-mix(in oklab, var(--hue-blue) 36%, var(--cloud));\n  --air: color-mix(in oklab, var(--hue-blue) 4%, var(--paper));\n  --liquid-bg: color-mix(in oklab, var(--hue-blue) 16%, var(--paper));\n  --glass-edge: color-mix(in oklab, var(--hue-blue) 35%, var(--ink-3));\n  --plate-rim: var(--paper);\n  --plate-well: color-mix(in oklab, var(--hue-grey) 12%, var(--paper));\n  --metal: color-mix(in oklab, var(--hue-grey) 62%, var(--paper));\n  --metal-shade: color-mix(in oklab, var(--hue-grey) var(--depth-shade), var(--shade));\n  --metal-in: color-mix(in oklab, var(--hue-grey) 50%, var(--shade));\n  --hob: color-mix(in oklab, var(--ink) 78%, var(--bg));\n  --seedhead: color-mix(in oklab, var(--hue-gold) 55%, var(--hue-brown));\n  --berry: var(--hue-red);\n  --berry-shade: color-mix(in oklab, var(--hue-red) var(--depth-shade), var(--shade));\n  --seed: color-mix(in oklab, var(--hue-gold) 55%, var(--paper));\n  --leaf: var(--hue-green);\n  --wood-1: color-mix(in oklab, var(--hue-brown) 26%, var(--bg));\n  --wood-2: color-mix(in oklab, var(--hue-brown) 32%, var(--bg));\n  --wood-line: color-mix(in oklab, var(--hue-brown) 46%, var(--bg));\n  --bowl: color-mix(in oklab, var(--hue-teal) 38%, var(--paper));\n  --bowl-in: color-mix(in oklab, var(--hue-teal) 18%, var(--paper));\n  --board: color-mix(in oklab, var(--hue-brown) 62%, var(--bg));\n  --crust: color-mix(in oklab, var(--hue-gold) 60%, var(--hue-brown));\n  --cheese: color-mix(in oklab, var(--hue-gold) 45%, var(--paper));\n  --pepperoni: color-mix(in oklab, var(--hue-red) 85%, var(--shade));\n  --note-paper: var(--paper);\n  --note-rule: color-mix(in oklab, var(--hue-blue) 28%, var(--paper));\n  --note-margin: color-mix(in oklab, var(--hue-red) 50%, var(--paper));\n  --thatch: color-mix(in oklab, var(--hue-gold) 55%, var(--hue-brown));\n  --thatch-shade: color-mix(in oklab, var(--thatch) var(--depth-shade), var(--shade));\n  --daub: color-mix(in oklab, var(--hue-brown) 28%, var(--paper));\n  --daub-shade: color-mix(in oklab, var(--daub) var(--depth-shade), var(--shade));\n  --stone: color-mix(in oklab, var(--hue-grey) 40%, var(--paper));\n  --stone-shade: color-mix(in oklab, var(--stone) var(--depth-shade), var(--shade));\n  --tile: color-mix(in oklab, var(--hue-red) 70%, var(--hue-brown));\n  --tile-shade: color-mix(in oklab, var(--tile) var(--depth-shade), var(--shade));\n  --road: color-mix(in oklab, var(--hue-grey) 55%, var(--bg));\n  --road-line: color-mix(in oklab, var(--hue-grey) 25%, var(--paper));\n  --hull: color-mix(in oklab, var(--hue-brown) 70%, var(--shade));\n  --field: color-mix(in oklab, var(--hue-gold) 45%, var(--hill-mid));\n  --era-iron: color-mix(in oklab, var(--hue-brown) 34%, var(--bg));\n  --era-roman: color-mix(in oklab, var(--hue-red) 28%, var(--bg));\n  --era-iron-text: color-mix(in oklab, var(--hue-brown) 55%, var(--ink));\n  --era-roman-text: color-mix(in oklab, var(--hue-red) 62%, var(--ink));\n  --store: var(--paper);\n  --store-edge: var(--ink-3);\n  --store-ltm: color-mix(in oklab, var(--hue-teal) 7%, var(--paper));\n  --funnel: color-mix(in oklab, var(--hue-blue) 12%, var(--bg));\n  --info-pale: color-mix(in oklab, var(--hue-blue) 30%, var(--paper));\n  --item: color-mix(in oklab, var(--ink) 30%, var(--paper));\n  --acid: var(--hue-teal);\n  --acid-edge: color-mix(in oklab, var(--hue-teal) var(--depth-shade), var(--shade));\n  --acid-liquid: color-mix(in oklab, var(--hue-teal) 12%, var(--paper));\n  --marble: color-mix(in oklab, var(--hue-grey) 22%, var(--cloud));\n  --marble-shade: color-mix(in oklab, var(--hue-grey) 55%, var(--cloud));\n  --solid-p: color-mix(in oklab, var(--hue-grey) 55%, var(--paper));\n  --solid-p-edge: color-mix(in oklab, var(--hue-grey) 70%, var(--shade));\n  --bubble: color-mix(in oklab, var(--hue-teal) 45%, var(--ink-3));\n  --product: color-mix(in oklab, var(--hue-purple) 85%, var(--shade));\n  --product-o: var(--hue-purple);\n  --product-edge: color-mix(in oklab, var(--hue-purple) 60%, var(--shade));\n  --product-text: color-mix(in oklab, var(--hue-purple) 72%, var(--ink));\n  --wall-line: color-mix(in oklab, var(--hue-blue) 14%, var(--bg));\n  --marble-top: var(--cloud);\n  --on-gold: var(--shade);\n  --knockout: color-mix(in oklab, var(--bg) 86%, transparent);\n  /* ---- kit additions (library v1): generic roles every model may use ---- */\n  /* focus and comparison: the one thing being taught now, and what it is compared with */\n  --focus: var(--hue-purple);\n  --focus-pale: color-mix(in oklab, var(--hue-purple) 18%, var(--bg));\n  --focus-text: color-mix(in oklab, var(--hue-purple) 72%, var(--ink));\n  --compare: var(--hue-teal);\n  --compare-pale: color-mix(in oklab, var(--hue-teal) 18%, var(--bg));\n  --compare-text: color-mix(in oklab, var(--hue-teal) 72%, var(--ink));\n  --neutral: color-mix(in oklab, var(--ink) 30%, var(--bg));\n  --grid-line: color-mix(in oklab, var(--ink) 12%, var(--bg));\n  --axis: var(--ink-2);\n  /* eras and periods: six tinted bands that stay distinct in every theme, each with a readable text tone */\n  --era-1: color-mix(in oklab, var(--hue-brown) 40%, var(--bg));\n  --era-1-text: color-mix(in oklab, var(--hue-brown) 55%, var(--ink));\n  --era-2: color-mix(in oklab, var(--hue-red) 30%, var(--bg));\n  --era-2-text: color-mix(in oklab, var(--hue-red) 62%, var(--ink));\n  --era-3: color-mix(in oklab, var(--hue-green) 34%, var(--bg));\n  --era-3-text: color-mix(in oklab, var(--hue-green) 60%, var(--ink));\n  --era-4: color-mix(in oklab, var(--hue-blue) 30%, var(--bg));\n  --era-4-text: color-mix(in oklab, var(--hue-blue) 62%, var(--ink));\n  --era-5: color-mix(in oklab, var(--hue-gold) 42%, var(--bg));\n  --era-5-text: color-mix(in oklab, var(--hue-gold) 50%, var(--ink));\n  --era-6: color-mix(in oklab, var(--hue-purple) 30%, var(--bg));\n  --era-6-text: color-mix(in oklab, var(--hue-purple) 62%, var(--ink));\n  /* place value: one colour per column, the same in every model */\n  --pv-ones: var(--hue-gold);\n  --pv-tens: var(--hue-blue);\n  --pv-hundreds: var(--hue-green);\n  --pv-thousands: var(--hue-purple);\n  --pv-ones-text: color-mix(in oklab, var(--hue-gold) 55%, var(--ink));\n  --pv-tens-text: color-mix(in oklab, var(--hue-blue) 72%, var(--ink));\n  --pv-hundreds-text: color-mix(in oklab, var(--hue-green) 65%, var(--ink));\n  --pv-thousands-text: color-mix(in oklab, var(--hue-purple) 72%, var(--ink));\n  /* land types for landscape layers */\n  --sand: color-mix(in oklab, var(--hue-gold) 40%, var(--bg));\n  --sand-far: color-mix(in oklab, var(--hue-gold) 22%, var(--haze));\n  --sand-shade: color-mix(in oklab, var(--sand) var(--depth-shade), var(--shade));\n  --snow: var(--cloud);\n  --snow-shade: color-mix(in oklab, var(--hue-blue) 18%, var(--cloud));\n  --soil: color-mix(in oklab, var(--hue-brown) 62%, var(--bg));\n  --soil-deep: color-mix(in oklab, var(--hue-brown) 80%, var(--shade));\n  --trunk: color-mix(in oklab, var(--hue-brown) 80%, var(--shade));\n  --canopy: var(--hue-green);\n  --canopy-shade: var(--hill-shade);\n  /* simple figures: flat tones, no faces needed */\n  --person-1: color-mix(in oklab, var(--hue-brown) 30%, var(--paper));\n  --person-2: color-mix(in oklab, var(--hue-brown) 75%, var(--shade));\n  --cloth-1: var(--hue-blue);\n  --cloth-2: var(--hue-teal);\n  --cloth-3: var(--hue-orange);\n}\n/* ---- 3. THEMES: each theme is ONLY a set of base tokens ---- */\n.theme-primary {\n  /* warm, playful, ages 5-11 */\n  --theme-name: "Primary";\n  --f-head: "Lexend", system-ui, sans-serif;\n  --f-label: "Lexend", system-ui, sans-serif;\n  --w-head: 600;\n  --w-label: 600;\n  --w-body: 500;\n  --w-strong: 700;\n  --track-head: -0.01em;\n  --bg: #fff8ee;\n  --paper: #ffffff;\n  --panel: #fbf0e1;\n  --ink: #2a2019;\n  --ink-2: #5e5045;\n  --ink-3: #786a5d;\n  --rule: #eadfcf;\n  --shade: #1e2a22;\n  --cloud: #ffffff;\n  --on-hue: #ffffff;\n  --hue-blue: #2b78cc;\n  --hue-red: #e0533f;\n  --hue-green: #5a9e55;\n  --hue-gold: #f2a93b;\n  --hue-teal: #13897a;\n  --hue-purple: #7a55c8;\n  --hue-orange: #e8783a;\n  --hue-brown: #a88b73;\n  --hue-grey: #9aa0a8;\n  --lift: drop-shadow(0 4px 10px rgba(80, 50, 20, 0.16));\n  --shadow-k: 14%;\n  --edge-w: 0px;\n  --edge-col: transparent;\n  --r-card: 18px;\n  --r-pill: 27px;\n  --r-mark: 4px;\n  --sw-hair: 1.5px;\n  --sw-rule: 2px;\n  --sw-struct: 3px;\n  --sw-arrow: 6px;\n  --sw-data: 6px;\n  --sw-lead: 2.5px;\n  --grain: 0;\n  --grain-display: none;\n}\n.theme-secondary {\n  /* refined, editorial, ages 11-18 */\n  --theme-name: "Secondary";\n  --f-head: "Fraunces", Georgia, serif;\n  --f-label: "Inter", system-ui, sans-serif;\n  --w-head: 500;\n  --w-label: 600;\n  --w-body: 500;\n  --w-strong: 700;\n  --track-head: -0.015em;\n  --bg: #f7f6f2;\n  --paper: #ffffff;\n  --panel: #efede7;\n  --ink: #14161b;\n  --ink-2: #4a4e57;\n  --ink-3: #666971;\n  --rule: #d9d5cb;\n  --shade: #0e1014;\n  --cloud: #ffffff;\n  --on-hue: #ffffff;\n  --hue-blue: #2d5bd8;\n  --hue-red: #d8432a;\n  --hue-green: #3e8e55;\n  --hue-gold: #c98a12;\n  --hue-teal: #0f7f6e;\n  --hue-purple: #6a4bc4;\n  --hue-orange: #da6a28;\n  --hue-brown: #9a7a5e;\n  --hue-grey: #8e949c;\n  --lift: drop-shadow(0 6px 14px rgba(20, 20, 30, 0.1));\n  --shadow-k: 12%;\n  --edge-w: 0px;\n  --edge-col: transparent;\n  --r-card: 8px;\n  --r-pill: 8px;\n  --r-mark: 2px;\n  --sw-hair: 1.5px;\n  --sw-rule: 1.5px;\n  --sw-struct: 2.5px;\n  --sw-arrow: 4px;\n  --sw-data: 5px;\n  --sw-lead: 2px;\n  --grain: 0;\n  --grain-display: none;\n}\n.theme-night {\n  /* dark, for dim rooms and blackout blinds */\n  --theme-name: "Night";\n  --f-head: "Inter", system-ui, sans-serif;\n  --f-label: "Inter", system-ui, sans-serif;\n  --w-head: 600;\n  --w-label: 600;\n  --w-body: 500;\n  --w-strong: 700;\n  --track-head: -0.02em;\n  --bg: #10141c;\n  --paper: #1b2131;\n  --panel: #171c28;\n  --ink: #eef1f6;\n  --ink-2: #b9c0cc;\n  --ink-3: #828a9a;\n  --rule: #2a3242;\n  --shade: #04060a;\n  --cloud: #d9e2ee;\n  --on-hue: #0e121a;\n  --hue-blue: #6ea8ff;\n  --hue-red: #ff7a62;\n  --hue-green: #5cc48a;\n  --hue-gold: #ffc452;\n  --hue-teal: #3fd0b8;\n  --hue-purple: #b39bff;\n  --hue-orange: #ff9a52;\n  --hue-brown: #c6a387;\n  --hue-grey: #9aa4b4;\n  --lift: drop-shadow(0 8px 18px rgba(0, 0, 0, 0.55));\n  --shadow-k: 45%;\n  --edge-w: 0px;\n  --edge-col: transparent;\n  --r-card: 14px;\n  --r-pill: 27px;\n  --r-mark: 3px;\n  --sw-hair: 1.5px;\n  --sw-rule: 1.5px;\n  --sw-struct: 2.5px;\n  --sw-arrow: 5px;\n  --sw-data: 5px;\n  --sw-lead: 2px;\n  --grain: 0;\n  --grain-display: none;\n}\n.theme-bold {\n  /* graphic, high contrast: black keylines, flat saturated fills */\n  --theme-name: "Bold";\n  --f-head: "Archivo", system-ui, sans-serif;\n  --f-label: "Archivo", system-ui, sans-serif;\n  --w-head: 800;\n  --w-label: 700;\n  --w-body: 600;\n  --w-strong: 800;\n  --track-head: -0.02em;\n  --bg: #ffffff;\n  --paper: #ffffff;\n  --panel: #f1f1f1;\n  --ink: #000000;\n  --ink-2: #1e1e1e;\n  --ink-3: #5a5a5a;\n  --rule: #000000;\n  --shade: #000000;\n  --cloud: #ffffff;\n  --on-hue: #ffffff;\n  --hue-blue: #0050ff;\n  --hue-red: #f2241b;\n  --hue-green: #00a651;\n  --hue-gold: #ffc400;\n  --hue-teal: #00a3a3;\n  --hue-purple: #7b2cff;\n  --hue-orange: #ff7a00;\n  --hue-brown: #8b5a2b;\n  --hue-grey: #8a8a8a;\n  --lift: drop-shadow(4px 4px 0 #000);\n  --shadow-k: 22%;\n  --edge-w: 3px;\n  --edge-col: #000000;\n  --r-card: 0px;\n  --r-pill: 0px;\n  --r-mark: 0px;\n  --sw-hair: 2px;\n  --sw-rule: 3px;\n  --sw-struct: 3.5px;\n  --sw-arrow: 7px;\n  --sw-data: 7px;\n  --sw-lead: 3px;\n  --grain: 0;\n  --grain-display: none;\n}\n.theme-riso {\n  /* risograph print: spot inks on warm paper, grain, offset registration */\n  --theme-name: "Riso";\n  --f-head: "Fraunces", Georgia, serif;\n  --f-label: "Lexend", system-ui, sans-serif;\n  --w-head: 600;\n  --w-label: 500;\n  --w-body: 400;\n  --w-strong: 600;\n  --track-head: -0.01em;\n  --bg: #f2ede2;\n  --paper: #fbf8f1;\n  --panel: #eae3d4;\n  --ink: #2b2b3a;\n  --ink-2: #545468;\n  --ink-3: #65636f;\n  --rule: #d8cfbd;\n  --shade: #2b2b3a;\n  --cloud: #fbf8f1;\n  --on-hue: #fbf8f1;\n  --hue-blue: #3255a4;\n  --hue-red: #ff665e;\n  --hue-green: #00a95c;\n  --hue-gold: #ffb511;\n  --hue-teal: #00838a;\n  --hue-purple: #765ba7;\n  --hue-orange: #ff6c2f;\n  --hue-brown: #a5704a;\n  --hue-grey: #9a98a0;\n  --lift: drop-shadow(3px 3px 0 rgba(255, 102, 94, 0.45));\n  --shadow-k: 16%;\n  --edge-w: 0px;\n  --edge-col: transparent;\n  --r-card: 4px;\n  --r-pill: 27px;\n  --r-mark: 2px;\n  --sw-hair: 1.5px;\n  --sw-rule: 2px;\n  --sw-struct: 2.5px;\n  --sw-arrow: 5px;\n  --sw-data: 5px;\n  --sw-lead: 2px;\n  --grain: 0.28;\n  --grain-display: inline;\n}\n/* ---- 4. SLIDE STYLES AND BUILD CLASSES (consume tokens only) ---- */\n.slide {\n  position: relative;\n  aspect-ratio: 16 / 9;\n  width: 100%;\n  border-radius: 14px;\n  overflow: hidden;\n  background: var(--bg);\n  box-shadow:\n    0 0 0 1px var(--page-rule),\n    0 24px 48px -28px var(--page-shadow);\n  transition: background var(--t-base) var(--ease-out);\n}\n.slide svg {\n  display: block;\n  width: 100%;\n  height: 100%;\n}\n.slide text {\n  font-family: var(--f-label);\n  fill: var(--ink);\n  font-weight: var(--w-body);\n}\n.slide .ts-title {\n  font-family: var(--f-head);\n  font-size: var(--fs-title);\n  font-weight: var(--w-head);\n  letter-spacing: var(--track-head);\n}\n.slide .ts-h3 {\n  font-family: var(--f-head);\n  font-size: var(--fs-h3);\n  font-weight: var(--w-head);\n}\n.slide .ts-label {\n  font-size: var(--fs-label);\n  font-weight: var(--w-label);\n}\n.slide .ts-small {\n  font-size: var(--fs-small);\n  fill: var(--ink-2);\n}\n.slide .ts-tiny {\n  font-size: var(--fs-min);\n  fill: var(--ink-2);\n}\n.slide .ts-cap {\n  font-size: var(--fs-cap);\n  fill: var(--ink-2);\n}\n.slide .ts-num {\n  font-size: var(--fs-num);\n  font-weight: var(--w-strong);\n  font-variant-numeric: tabular-nums;\n}\n.slide .ts-big {\n  font-size: var(--fs-big);\n  font-weight: var(--w-strong);\n  font-variant-numeric: tabular-nums;\n}\n.slide .ts-eq {\n  font-size: var(--fs-eq);\n  font-weight: var(--w-strong);\n}\n.slide .ts-badge {\n  font-size: var(--fs-badge);\n  font-weight: var(--w-strong);\n  fill: var(--on-hue);\n}\n.slide .ts-frac {\n  font-size: var(--fs-label);\n  font-weight: var(--w-strong);\n}\n.slide .strong {\n  font-weight: var(--w-strong);\n}\n.slide .muted {\n  fill: var(--ink-3);\n}\n.slide .lift {\n  filter: var(--lift);\n}\n.slide .body {\n  stroke: var(--edge-col);\n  stroke-width: var(--edge-w);\n  stroke-linejoin: round;\n}\n.slide .grain {\n  display: var(--grain-display);\n  opacity: var(--grain);\n  mix-blend-mode: multiply;\n  pointer-events: none;\n}\n\n/* step machinery: data-s = shown from step k, data-h = hidden from step k, data-c = class from step k */\n.slide [data-s],\n.slide [data-h],\n.slide [data-c] {\n  transition:\n    opacity var(--t-build-enter) var(--ease-out) var(--d, 0ms),\n    transform var(--t-build-move) var(--ease-io) var(--d, 0ms),\n    stroke-dashoffset var(--t-build-draw) var(--ease-io) var(--d, 0ms),\n    fill var(--t-build-enter) var(--ease-out) var(--d, 0ms),\n    stroke var(--t-build-enter) var(--ease-out) var(--d, 0ms);\n}\n.slide .quiet {\n  opacity: var(--recede-quiet);\n}\n.slide .soft {\n  opacity: var(--recede-soft);\n} /* secondary in the summary: still readable */\n.slide [data-c].quiet,\n.slide [data-c].soft {\n  transition: opacity var(--t-recede) var(--ease-out);\n}\n.slide .off {\n  opacity: 0;\n}\n.slide .rise,\n.slide .pop,\n.slide .wipe {\n  transform-box: fill-box;\n}\n.slide .rise {\n  transform-origin: center;\n}\n.slide .off.rise {\n  transform: translateY(18px);\n}\n.slide .pop {\n  transform-origin: center;\n}\n.slide .off.pop {\n  transform: scale(0.55);\n}\n.slide .wipe {\n  transform-origin: left center;\n}\n.slide .off.wipe {\n  transform: scaleX(0);\n  opacity: 1;\n}\n.slide .draw {\n  stroke-dasharray: 1 1;\n  stroke-dashoffset: 0;\n}\n.slide .off.draw {\n  opacity: 1;\n  stroke-dashoffset: 1;\n}\n.slide [data-s].fly,\n.slide [data-h].snap {\n  transition:\n    opacity var(--t-quick) linear var(--d, 0ms),\n    transform var(--t-build-move) var(--ease-io) var(--d, 0ms),\n    fill var(--t-build-enter) var(--ease-out) var(--d, 0ms),\n    stroke var(--t-build-enter) var(--ease-out) var(--d, 0ms);\n}\n.slide .off.fly {\n  transform: translate(var(--fx), var(--fy));\n  opacity: 0;\n}\n.slide.instant * {\n  transition: none !important;\n}\n.slide:not(.playing) .live {\n  opacity: 0;\n}\n.slide.playing .ghost {\n  opacity: 0;\n}\n.slide .ghost,\n.slide .live {\n  transition: opacity var(--t-base) var(--ease-out);\n}\n.slide.playing .vflow {\n  animation: vflow var(--loop-vapour) linear infinite;\n}\n@keyframes vflow {\n  to {\n    stroke-dashoffset: -18;\n  }\n}\n.slide.playing .rflow {\n  animation: rflow var(--loop-river) linear infinite;\n}\n@keyframes rflow {\n  to {\n    stroke-dashoffset: -40;\n  }\n}\n.slide.playing .drop {\n  animation: fall var(--loop-rain) linear infinite;\n  animation-delay: calc(var(--rd, 0s) * 2);\n}\n@keyframes fall {\n  0% {\n    transform: translateY(-26px);\n    opacity: 0;\n  }\n  25% {\n    opacity: 1;\n  }\n  100% {\n    transform: translateY(34px);\n    opacity: 0;\n  }\n}\n.slide .statebox {\n  transition: opacity var(--t-base) var(--ease-out);\n}\n.slide .statebox.dim {\n  opacity: var(--recede-quiet);\n}\n@media (prefers-reduced-motion: reduce) {\n  .slide [data-s],\n  .slide [data-h],\n  .slide [data-c],\n  .slide [data-s].fly,\n  .slide [data-h].snap {\n    transition:\n      opacity 160ms linear,\n      fill 160ms linear,\n      stroke 160ms linear !important;\n  }\n  .slide .off.rise,\n  .slide .off.pop,\n  .slide .off.fly {\n    transform: none;\n  }\n  .slide .off.wipe {\n    transform: none;\n    opacity: 0;\n  }\n  .slide .off.draw {\n    opacity: 0;\n  }\n  .slide.playing .vflow,\n  .slide.playing .rflow,\n  .slide.playing .drop {\n    animation: none;\n  }\n}\n/* kit additions */\n.slide .ts-date {\n  font-size: var(--fs-label);\n  font-weight: var(--w-strong);\n  font-variant-numeric: tabular-nums;\n}\n.slide .ts-era {\n  font-size: var(--fs-small);\n  font-weight: var(--w-strong);\n}\n.slide .ts-axis {\n  font-size: var(--fs-min);\n  fill: var(--ink-2);\n  font-variant-numeric: tabular-nums;\n}\n.slide .caption {\n  font-size: var(--fs-cap);\n  fill: var(--ink-2);\n}\n/* labels that may cross a hairline (axis values, zoom connectors) get a ground-coloured halo */\n.slide .ts-axis,\n.slide .halo {\n  paint-order: stroke;\n  stroke: var(--bg);\n  stroke-width: 6px;\n  stroke-linejoin: round;\n}\n.slide .halo-paper {\n  paint-order: stroke;\n  stroke: var(--paper);\n  stroke-width: 6px;\n  stroke-linejoin: round;\n}\n\n/* ---- instant jumps (libfix): a jump to a build (Back, a still, a reset) lands at once. This sits last and\n   is more specific than every build transition, including the reduced-motion fade above (both are\n   !important; equal specificity let the later reduced-motion rule win, so a jump faded for 160 ms). */\n.slide.instant,\n.slide.instant *,\n.slide.instant [data-s],\n.slide.instant [data-h],\n.slide.instant [data-c],\n.slide.instant [data-s].fly,\n.slide.instant [data-h].snap,\n.slide.instant [data-c].quiet,\n.slide.instant [data-c].soft {\n  transition: none !important;\n  animation-duration: 0s !important;\n  animation-delay: 0s !important;\n}\n';
